import sys
def main():
    t = sys.stdin.read().split()
    k, q = int(t[0]), int(t[1])
    # g[l][last][r]: strings of length l, adjacent digits distinct, first digit != last, digit sum = r (mod k)
    g = [[[0] * k for _ in range(11)] for _ in range(20)]
    for last in range(11):
        g[0][last][0] = 1
    for l in range(1, 20):
        prev = g[l - 1]
        for last in range(11):
            row = g[l][last]
            for d in range(10):
                if d == last:
                    continue
                src = prev[d]
                for r in range(k):
                    row[(r + d) % k] += src[r]
    def f(n):
        if n < 0:
            return 0
        if n == 0:
            return 1
        D = list(map(int, str(n)))
        L = len(D)
        res = 1  # the number 0
        for l in range(1, L):
            for d in range(1, 10):
                res += g[l - 1][d][(-d) % k]
        s = 0
        prevd = 10
        for i, cd in enumerate(D):
            for d in range(1 if i == 0 else 0, cd):
                if d != prevd:
                    res += g[L - i - 1][d][(-s - d) % k]
            if cd == prevd:
                break
            s += cd
            prevd = cd
        else:
            if s % k == 0:
                res += 1
        return res
    out = []
    for i in range(q):
        L, R = int(t[2 + 2 * i]), int(t[3 + 2 * i])
        out.append(str(f(R) - f(L - 1)))
    print("\n".join(out))
main()

import sys
def main():
    t = sys.stdin.read().split()
    n = int(t[0])
    c = [int(x) for x in t[1:1 + n]]
    pos = {}
    for i, x in enumerate(c):
        pos.setdefault(x, []).append(i)
    later = [[k for k in pos[c[i]] if k > i + 1] for i in range(n)]
    dp = [[0] * (n + 2) for _ in range(n + 2)]  # dp[i][j] for closed [i, j]; 0 when j < i
    for i in range(n - 1, -1, -1):
        di = dp[i]
        di1 = dp[i + 1]
        di[i] = 1
        li = later[i]
        for j in range(i + 1, n):
            best = 1 + di1[j]
            if c[i] == c[i + 1]:
                v = 1 + dp[i + 2][j]
                if v < best:
                    best = v
            for k in li:
                if k > j:
                    break
                v = di1[k - 1] + dp[k + 1][j]
                if v < best:
                    best = v
            di[j] = best
    print(dp[0][n - 1])
main()

import sys
def main():
    MOD = 10 ** 9 + 7
    t = sys.stdin.buffer.read().split()
    n = int(t[0])
    w = [0] + [int(x) for x in t[1:1 + n]]
    adj = [[] for _ in range(n + 1)]
    base = 1 + n
    for i in range(n - 1):
        u = int(t[base + 2 * i]); v = int(t[base + 2 * i + 1])
        adj[u].append(v); adj[v].append(u)
    parent = [0] * (n + 1)
    parent[1] = -1
    order = [1]
    for x in order:
        for y in adj[x]:
            if y != parent[x]:
                parent[y] = x; order.append(y)
    inc = w[:]           # best value with x chosen
    exc = [0] * (n + 1)  # best value with x not chosen
    ci = [1] * (n + 1)
    ce = [1] * (n + 1)
    for x in reversed(order):
        p = parent[x]
        if p < 0:
            continue
        inc[p] += exc[x]
        ci[p] = ci[p] * ce[x] % MOD
        if inc[x] > exc[x]:
            bv, bc = inc[x], ci[x]
        elif exc[x] > inc[x]:
            bv, bc = exc[x], ce[x]
        else:
            bv, bc = inc[x], (ci[x] + ce[x]) % MOD
        exc[p] += bv
        ce[p] = ce[p] * bc % MOD
    if inc[1] > exc[1]:
        print(inc[1], ci[1])
    elif exc[1] > inc[1]:
        print(exc[1], ce[1])
    else:
        print(inc[1], (ci[1] + ce[1]) % MOD)
main()
